import json
def solve(inp):
    g=[row[:] for row in inp]
    from collections import Counter
    H,W=len(g),len(g[0])
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    seen=set(); out=[r[:] for r in g]
    # 1) find shapes (non-bg, non-8)
    def get(cells): return tuple(sorted((r,c)) for r,c in cells)
    components=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]==bg: continue
            col=g[r][c]
            stack=[(r,c)]; comp=[]
            while stack:
                a,b=stack.pop()
                if (a,b) in seen or not(0<=a<H and 0<=b<W) or (g[a][b]!=col and col!=9 and g[a][b]!=8) : continue
                if (a,b) in seen: continue
                seen.add((a,b)); comp.append((a,b))
                for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                    na,nb=a+dr,b+dc
                    if 0<=na<H and 0<=nb<W and g[na][nb]==col: stack.append((na,nb))
            components.append(comp)
    shapes=[]; noise=[]
    for comp in components:
        rs={r for r,c in comp}; cs={c for r,c in comp}
        if len(rs)==3 and len(cs)==3: shapes.append((col,comp))
        else: noise.extend(((r,c,g[r][c])) for r,c in comp)
    # paint shape color on top-right L
    for col,comp in shapes:
        for r,c in comp:
            out[r][W-1]=col
    # 2) recolor noise
    for r,c,v in noise:
        out[r][c]=None
    return out
