def comps(g,bg):
    H,W=len(g),len(g[0]); seen=set(); cs=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]==bg or (r,c) in seen: continue
            col=g[r][c]; st=[(r,c)]; comp=[]
            while st:
                a,b=st.pop()
                if (a,b) in seen: continue
                seen.add((a,b)); comp.append((a,b))
                for dr in(-1,0,1):
                    for dc in(-1,0,1):
                        na,nb=a+dr,b+dc
                        if 0<=na<H and 0<=nb<W and g[na][nb]==col: st.append((na,nb))
            cs.append((col,tuple(sorted(comp))))
    return cs
